const { spawnSync } = require('child_process');

const binaryPath = process.argv[2];
if (!binaryPath) {
    console.error('Usage: node extract.js <binary_path>');
    process.exit(1);
}

// Use objdump to dump all sections with their content
const result = spawnSync('objdump', ['-s', binaryPath], {
    encoding: 'utf8'
});

if (result.error) {
    console.error('Error running objdump:', result.error);
    process.exit(1);
}

const output = result.stdout;
const memoryMap = {};

// Parse objdump output to extract memory addresses and values
const lines = output.split('\n');

for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Look for lines with addresses (they start with hex address)
    if (line.match(/^ [0-9a-f]+ /)) {
        const parts = line.trim().split(/\s+/);
        if (parts.length >= 2) {
            const address = parseInt(parts[0], 16);
            const hexBytes = parts.slice(1, 17); // First 16 hex bytes

            // Process each 4-byte word (little-endian)
            for (let j = 0; j < hexBytes.length - 3; j += 4) {
                const wordBytes = hexBytes.slice(j, j + 4);
                const wordValue = parseInt(wordBytes.reverse().join(''), 16);
                memoryMap[(address + j).toString()] = wordValue;
            }
        }
    }
}

